<?php require dirname(__DIR__).'/bootstrap.php';header('Cache-Control: no-store');if(isset($_SESSION['admin']))go('index.php');
if($_SERVER['REQUEST_METHOD']==='POST'){check();$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$a=q('SELECT * FROM login_attempts WHERE ip_hash=?',[$ip])->fetch();if($a&&$a['attempts']>=5&&time()-(int)$a['last_attempt']<900){flash('Đăng nhập sai quá nhiều. Hãy thử lại sau 15 phút.');go('login.php');}
$u=q('SELECT * FROM admins WHERE username=?',[substr((string)($_POST['username']??''),0,80)])->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password_hash'])){q('DELETE FROM login_attempts WHERE ip_hash=?',[$ip]);session_regenerate_id(true);$_SESSION['admin']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));go('index.php');}
$n=($a&&time()-(int)$a['last_attempt']<900)?(int)$a['attempts']+1:1;q('INSERT INTO login_attempts(ip_hash,attempts,last_attempt) VALUES(?,?,?) ON DUPLICATE KEY UPDATE attempts=?,last_attempt=?',[$ip,$n,time(),$n,time()]);flash('Tên đăng nhập hoặc mật khẩu không đúng.');go('login.php');}head('Đăng nhập quản trị','../');?>
<main class="login card"><p class="eyebrow">PORTFOLIO / ADMIN</p><h1>Chào trở lại.</h1><p>Đăng nhập để quản lý nội dung của bạn.</p><?php notice();?><form method="post"><?=csrf()?><label>Tên đăng nhập<input name="username" required maxlength="80" autocomplete="username"></label><label>Mật khẩu<input name="password" type="password" required autocomplete="current-password"></label><button>Đăng nhập →</button></form><p><a href="../">← Về website</a></p></main></body></html>
